window.docContents[216].resolve({"/Types-and-expressions/#Core-C______--Types-and-expressions":{"contents":"One typing rule and one evaluation rule per construction of Expr. The typing rules live in Typing.expr and the evaluation rules in Eval.expr, each in the comment of the case that implements it. Where C++17 leaves the evaluation order unspecified, Core C++ evaluates left to right. The second half of the chapter holds the composite and recursive types, objects, pointers and vectors, whose expressions denote locations.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Core C++","header":"3. Types and expressions","id":"/Types-and-expressions/#Core-C______--Types-and-expressions"}});